#include <stdio.h>

int main (){

    int i = 1;

    
    while (i <= 10)
    //O que faz: inicia um loop while;
    //A condição (i <= 10) é verificada antes de cada execução do bloco;
    //Enquanto "i" for menor ou igual a 10, o código dentro do { } será executado;
    {
        printf("%d\n", i);  
        i++;
    }
    






    return 0;
}